using Microsoft.Extensions.Hosting;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Options;using Microsoft.Extensions.Logging;
var builder=Host.CreateApplicationBuilder();builder.Logging.ClearProviders();builder.Services.AddOptions<Config>().Validate(x=>!string.IsNullOrWhiteSpace(x.Name),"Name required").ValidateOnStart();
using var host=builder.Build();try{await host.StartAsync();}catch(OptionsValidationException){Console.WriteLine("startup rejected");}
class Config {public string Name {get;set;}="";}

